<?php

declare(strict_types=1);
require_once __DIR__.'/CompanyCredits.php';require_once __DIR__.'/CompanyExpenseSchema.php';

/** Current financial position, never a global report with a post-hoc company filter. */
final class CompanyReports
{
    private IssuerResourceAccess $acl;
    public const CAPABILITIES=[['reports','view'],['invoices','view'],['payments','view'],['credit_notes','view'],['expenses','view']];
    public function __construct(private $db,private string $p,private $guard=null){if(!preg_match('/^[A-Za-z0-9_]+$/D',$p))throw new InvalidArgumentException('Invalid table prefix');$this->acl=new IssuerResourceAccess($db,$p);}
    private function rows(string $sql,array $args=[]):array{return IssuerStorage::query($this->db,$sql,$args)->result_array();}
    private function authorize(int $issuer,int $actor):void{foreach(self::CAPABILITIES as [$feature,$cap])if(!$this->acl->can($issuer,$actor,$feature,$cap))throw new DomainException('company_report_access_denied');}
    private function transaction(int $issuer,int $actor,callable $work)
    {
        $this->authorize($issuer,$actor);CompanyCreditSchema::assertValid($this->db,$this->p);CompanyExpenseSchema::assertValid($this->db,$this->p);
        return IssuerTransaction::run($this->db,$this->p,['issuers_lock','issuers_registry','issuers_installation_identity','issuers_staff','issuers_resource_permissions','staff','creditnotes','credits','creditnote_refunds','invoices','issuers_invoice_documents','company_credit_documents','company_credit_entries','currencies','invoicepaymentrecords','company_payment_receipts','company_expenses','company_expense_categories','issuers_audit'],function()use($issuer,$actor,$work){$this->acl->lockFinancialIdentity($issuer,$actor);$this->authorize($issuer,$actor);if($this->guard!==null)($this->guard)();$result=$work();$this->authorize($issuer,$actor);if($this->guard!==null)($this->guard)();return $result;});
    }
    private static function amount($value):int{try{$amount=CompanyInvoiceAmounts::minor((string)$value);if($amount>CompanyInvoiceAmounts::MAX)throw new DomainException();return $amount;}catch(Throwable $e){throw new DomainException('company_report_balance_review');}}
    private static function sum(int &$target,int $amount):void{if($amount<0||$amount>PHP_INT_MAX-$target)throw new DomainException('company_report_balance_review');$target+=$amount;}
    private static function zero(string $currency):array{return ['currency'=>$currency,'invoiced'=>0,'received'=>0,'applied_credit'=>0,'receivable'=>0,'credit_issued'=>0,'credit_available'=>0,'credit_refunded'=>0,'expenses'=>0,'expense_tax'=>0,'invoice_count'=>0,'credit_count'=>0,'expense_count'=>0];}
    private function financial(int $issuer,int $actor):array
    {
        $totals=[];$creditDocs=[];$reader=new CompanyCredits($this->db,$this->p);$counts=['cancelled_invoices'=>0,'cancelled_credits'=>0,'cancelled_expenses'=>0];
        $currency=function(string $name)use(&$totals):string{if(!preg_match('/^[A-Z]{3}$/D',$name))throw new DomainException('company_report_balance_review');if(!isset($totals[$name]))$totals[$name]=self::zero($name);return $name;};
        foreach($this->rows('SELECT c.id,d.credit_id snapshot_id FROM '.$this->p.'creditnotes c LEFT JOIN '.$this->p.'company_credit_documents d ON d.credit_id=c.id AND d.issuer_id=c.issuer_id WHERE c.issuer_id=? ORDER BY c.id FOR UPDATE',[$issuer]) as $row){if($row['snapshot_id']===null)throw new DomainException('company_report_balance_review');$doc=$reader->inOwnedTransaction($issuer,$actor,$row['id']);$creditDocs[$doc['id']]=$doc;if($doc['status']===3){$counts['cancelled_credits']++;continue;}$name=$currency($doc['currency']);$totals[$name]['credit_count']++;foreach(['credit_issued'=>$doc['amounts']['total'],'credit_available'=>$doc['available'],'credit_refunded'=>$doc['refunded']] as $field=>$value)self::sum($totals[$name][$field],self::amount($value));}
        foreach($this->rows('SELECT i.id,i.clientid,i.currency,i.total,i.status,d.invoice_id snapshot_id,u.name currency_name FROM '.$this->p.'invoices i LEFT JOIN '.$this->p.'issuers_invoice_documents d ON d.invoice_id=i.id AND d.issuer_id=i.issuer_id LEFT JOIN '.$this->p.'currencies u ON u.id=i.currency WHERE i.issuer_id=? ORDER BY i.id FOR UPDATE',[$issuer]) as $invoice){
            if($invoice['snapshot_id']===null||$invoice['currency_name']===null)throw new DomainException('company_report_balance_review');$total=self::amount($invoice['total']);if($total<1)throw new DomainException('company_report_balance_review');$paid=0;$applied=0;$status=(int)$invoice['status'];if(!in_array($status,[1,2,3,4,5,6],true))throw new DomainException('company_report_balance_review');
            foreach($this->rows('SELECT id,invoiceid,amount,paymentmode,paymentmethod,date,transactionid,note FROM '.$this->p.'invoicepaymentrecords WHERE invoiceid=? FOR UPDATE',[$invoice['id']]) as $payment){$proof=$this->rows('SELECT request_key,input_hash FROM '.$this->p.'company_payment_receipts WHERE payment_id=? AND invoice_id=? AND issuer_id=?',[$payment['id'],$invoice['id'],$issuer]);if(count($proof)!==1)throw new DomainException('company_report_balance_review');$original=self::amount($payment['amount']);$reversals=$this->rows('SELECT amount FROM '.$this->p.'company_credit_entries WHERE issuer_id=? AND invoice_id=? AND native_id=? AND kind=?',[$issuer,$invoice['id'],$payment['id'],'manual_reverse']);if($reversals&&$payment['paymentmode']!=='company_manual')throw new DomainException('company_report_balance_review');foreach($reversals as $entry)self::sum($original,self::amount($entry['amount']));if($original>CompanyInvoiceAmounts::MAX)throw new DomainException('company_report_balance_review');$payload=['invoiceid'=>(int)$payment['invoiceid'],'amount'=>CompanyInvoiceAmounts::decimal($original),'paymentmode'=>$payment['paymentmode'],'paymentmethod'=>$payment['paymentmethod'],'date'=>$payment['date'],'transactionid'=>$payment['transactionid'],'note'=>$payment['note']];if(!hash_equals($proof[0]['input_hash'],hash('sha256',json_encode($payload,JSON_THROW_ON_ERROR))))throw new DomainException('company_report_balance_review');self::sum($paid,self::amount($payment['amount']));}
            foreach($this->rows('SELECT credit_id,amount FROM '.$this->p.'credits WHERE invoice_id=? FOR UPDATE',[$invoice['id']]) as $movement){$credit=$creditDocs[(int)$movement['credit_id']]??null;if(!$credit||$credit['client_id']!==(int)$invoice['clientid']||$credit['currency_id']!==(int)$invoice['currency'])throw new DomainException('company_report_balance_review');self::sum($applied,self::amount($movement['amount']));}
            if($paid>$total||$applied>$total-$paid||(($status===5||$status===6)&&($paid||$applied)))throw new DomainException('company_report_balance_review');$remaining=$total-$paid-$applied;
            if(($status===2&&$remaining!==0)||($status===3&&($remaining===0||$remaining===$total))||(in_array($status,[1,4],true)&&$remaining!==$total))throw new DomainException('company_report_balance_review');if($status===5){$counts['cancelled_invoices']++;continue;}if($status===6)continue;
            $name=$currency($invoice['currency_name']);$totals[$name]['invoice_count']++;foreach(['invoiced'=>$total,'received'=>$paid,'applied_credit'=>$applied,'receivable'=>$remaining] as $field=>$amount)self::sum($totals[$name][$field],$amount);
        }
        foreach($this->rows('SELECT e.currency,e.amount_cents,e.tax_cents,e.tax_rate,e.total_cents,e.state,c.issuer_id category_issuer FROM '.$this->p.'company_expenses e JOIN '.$this->p.'company_expense_categories c ON c.id=e.category_id WHERE e.issuer_id=? ORDER BY e.id FOR UPDATE',[$issuer]) as $expense){if((int)$expense['category_issuer']!==$issuer||!in_array($expense['state'],['recorded','cancelled'],true))throw new DomainException('company_report_balance_review');$base=(int)$expense['amount_cents'];$tax=(int)$expense['tax_cents'];$rate=(int)$expense['tax_rate'];$total=(int)$expense['total_cents'];if($base<1||$base>99999999999||$rate<0||$rate>10000||$tax!==intdiv($base*$rate+5000,10000)||$total!==$base+$tax)throw new DomainException('company_report_balance_review');if($expense['state']==='cancelled'){$counts['cancelled_expenses']++;continue;}$name=$currency($expense['currency']);$totals[$name]['expense_count']++;self::sum($totals[$name]['expenses'],$total);self::sum($totals[$name]['expense_tax'],$tax);}
        ksort($totals);foreach($totals as &$row)foreach(['invoiced','received','applied_credit','receivable','credit_issued','credit_available','credit_refunded','expenses','expense_tax'] as $field)$row[$field]=CompanyInvoiceAmounts::decimal($row[$field]);unset($row);return ['issuer_id'=>$issuer,'generated_at'=>date('Y-m-d H:i:s'),'basis'=>'current_position_not_historical_cashflow','currencies'=>array_values($totals),'counts'=>$counts];
    }
    public function financialPosition($issuer,$actor):array{$issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);return $this->transaction($issuer,$actor,fn():array=>$this->financial($issuer,$actor));}
    public function csv($issuer,$actor):string
    {
        $issuer=IssuerPolicy::id($issuer);$actor=IssuerPolicy::id($actor);return $this->transaction($issuer,$actor,function()use($issuer,$actor):string{$report=$this->financial($issuer,$actor);$stream=fopen('php://temp','w+');if(!$stream)throw new RuntimeException('issuer_report_export_failed');try{fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,['Empresa','Gerado em','Moeda','Faturas emitidas','Recebimentos nominais após estornos','Crédito aplicado','A receber','Créditos emitidos','Crédito disponível','Reembolsos líquidos registrados','Despesas registradas','Tributos de despesas','Qtd. faturas','Qtd. créditos','Qtd. despesas'],';', '"', '');foreach($report['currencies'] as $row)fputcsv($stream,[$issuer,$report['generated_at'],$row['currency'],$row['invoiced'],$row['received'],$row['applied_credit'],$row['receivable'],$row['credit_issued'],$row['credit_available'],$row['credit_refunded'],$row['expenses'],$row['expense_tax'],$row['invoice_count'],$row['credit_count'],$row['expense_count']],';','"','');rewind($stream);$csv=stream_get_contents($stream);if(!is_string($csv))throw new RuntimeException('issuer_report_export_failed');}finally{fclose($stream);}$json=json_encode(['sha256'=>hash('sha256',$csv),'basis'=>$report['basis'],'currencies'=>count($report['currencies'])],JSON_THROW_ON_ERROR);IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'issuers_audit(actor_id,event,issuer_id,subject_id,created_at,metadata_json) VALUES(?,?,?,?,?,?)',[$actor,'company_financial_report_exported',$issuer,$issuer,date('Y-m-d H:i:s'),$json]);$id=(int)$this->db->insert_id();if(!$this->rows('SELECT id FROM '.$this->p.'issuers_audit WHERE id=? AND issuer_id=? AND event=? AND metadata_json=?',[$id,$issuer,'company_financial_report_exported',$json]))throw new RuntimeException('issuer_report_export_failed');return $csv;});
    }
}
